window.docContents[186].resolve({"/Sets/#Sem___ntica-computacional-com-Lean--Conjuntos-e-Rela______es--Rela______es--Inversa":{"contents":"A inversa de uma relação troca a ordem dos argumentos, e é flip quem\nfaz isso. Em língua, é o que a voz passiva faz: Dorothy likes Toto e\nToto is liked by Dorothy descrevem o mesmo par, em ordens opostas.\n\n#check (flip likesR)\n\n\nflip likesR : Entity → Entity → Prop\n\n\nexample :\n    flip likesR .toto .dorothy =\n      likesR .dorothy .toto := rfl\n\n\n","context":"Semântica computacional com Lean\u0009Conjuntos e Relações\u0009Relações","header":"6.2.1. Inversa","id":"/Sets/#Sem___ntica-computacional-com-Lean--Conjuntos-e-Rela______es--Rela______es--Inversa"}});